    if (now >= bot.reactAt && now >= bot.pauseUntil) {
      if (bot.burstLeft <= 0) {
        bot.burstLeft = COMBAT.botBurstMin + Math.floor(Math.random() * (COMBAT.botBurstMax - COMBAT.botBurstMin));
