    bot.lastPos.set(bot.pos.x, 0, bot.pos.z);
    steer(bot, bot.moveTarget.x, bot.moveTarget.z, dt, colliders, bot.state === 'zone' ? PLAYER.sprintSpeed * 0.85 : PLAYER.walkSpeed);
