      } else if (item.kind === 'medkit') {
        bot.health = Math.min(100, bot.health + 50);
      } else if (item.kind === 'armor') {
        bot.armor = Math.min(PLAYER.armorMax, bot.armor + 50);
      } else if (item.kind.startsWith('ammo')) {
        const ammoKind = item.kind.slice(5);
